body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 20px;
    display: flex;
    justify-content: center;
    background-color: #f9f9f9;
}

.container {
    display: flex;
    flex-direction: row;
    width: 100%;
    max-width: 1800px;
    gap: 20px;
    height: 90vh;
}

#bubble-chart {
    flex: 1;
    border: 1px solid #e0e0e0;
    background-color: #fff;
    border-radius: 8px;
    position: relative;
    overflow: hidden;
}

#data-table {
    flex: 0 0 500px;
    border: 1px solid #e0e0e0;
    background-color: #fff;
    border-radius: 8px;
    overflow-y: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    padding: 12px 15px;
    text-align: left;
    border-bottom: 1px solid #f0f0f0;
    font-size: 14px;
}

th {
    background-color: #f8f9fa;
    position: sticky;
    top: 0;
    font-weight: 600;
    color: #333;
    z-index: 10;
}

tr {
    transition: background-color 0.2s;
}

tr:hover {
    background-color: #f1f1f1;
    cursor: pointer;
}

tr.highlighted {
    background-color: #fff3cd; /* Light yellow */
}

.tooltip {
    position: absolute;
    text-align: left;
    padding: 10px;
    font: 13px sans-serif;
    background: rgba(255, 255, 255, 0.95);
    border: 1px solid #ddd;
    border-radius: 4px;
    pointer-events: none;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    z-index: 100;
}

.tooltip h4 {
    margin: 0 0 5px 0;
    font-size: 14px;
    color: #333;
}

.tooltip p {
    margin: 0;
    color: #666;
}

.bubble {
    cursor: pointer;
    stroke: #fff;
    stroke-width: 1.5px;
    transition: opacity 0.2s;
}

.bubble:hover {
    stroke: #333;
    stroke-width: 2px;
}

.bubble.highlighted {
    stroke: #000;
    stroke-width: 3px;
    filter: drop-shadow(0 0 4px rgba(0,0,0,0.3));
}

.bubble-text {
    font-family: Arial, sans-serif;
    font-size: 10px;
    text-anchor: middle;
    alignment-baseline: central;
    pointer-events: none;
    fill: #333;
    font-weight: bold;
    text-shadow: 0 1px 0 rgba(255,255,255,0.5);
}

.legend-item {
    cursor: pointer;
}

.legend-item:hover text {
    font-weight: bold;
}

