// Format numbers for display (e.g., 1.64T)
const formatMarketCap = (val) => {
    if (!val || val === "N/A" || isNaN(val)) return "N/A";
    const num = +val;
    if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
    if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
    if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
    return num.toLocaleString();
};

// Main function
d3.csv("data/stock-descriptions.csv").then(data => {
    // Process data
    data.forEach(d => {
        d.marketCapVal = d.marketCap && d.marketCap !== "" ? +d.marketCap : null;
    });

    // --- Configuration ---
    const width = document.getElementById("bubble-chart").clientWidth;
    const height = document.getElementById("bubble-chart").clientHeight;

    // Get unique sectors
    const sectors = Array.from(new Set(data.map(d => d.sector))).filter(s => s).sort();

    // Color scale for sectors
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeTableau10); // Nice categorical colors

    // Calculate cluster centers for sectors
    // Arrange centers in a grid or circle to keep them "centered reasonably"
    const sectorCenters = {};
    const centerRadius = Math.min(width, height) * 0.3;
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI;
        // Adjust centers to be around the middle of the canvas
        sectorCenters[sector] = {
            x: width / 2 + Math.cos(angle) * centerRadius,
            y: height / 2 + Math.sin(angle) * centerRadius * 0.8 // Compress Y slightly
        };
    });

    // Bubble size scale
    // Find min and max market cap for sizing
    const caps = data.map(d => d.marketCapVal).filter(v => v !== null);
    const minCap = d3.min(caps);
    const maxCap = d3.max(caps);

    // ETF (no market cap) size
    const etfSize = 15; // fixed size for ETFs

    const rScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([10, 60]); // Radius range

    // Assign initial properties
    const nodes = data.map(d => {
        const r = d.marketCapVal ? rScale(d.marketCapVal) : etfSize;
        return {
            ...d,
            r: r,
            x: width / 2 + (Math.random() - 0.5) * 50,
            y: height / 2 + (Math.random() - 0.5) * 50
        };
    });

    // --- Bubble Chart ---
    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .call(d3.zoom().on("zoom", (event) => {
            container.attr("transform", event.transform);
        }));

    const container = svg.append("g");

    // Force Simulation
    const simulation = d3.forceSimulation(nodes)
        .force("charge", d3.forceManyBody().strength(5)) // Positive charge to attract slightly? No, usually negative.
        // Actually, we want them to cluster. forceManyBody with negative value pushes them apart.
        // We will use forceX/forceY to pull them to centers, and forceCollide to prevent overlap.
        .force("x", d3.forceX(d => d.sector ? sectorCenters[d.sector].x : width/2).strength(0.15))
        .force("y", d3.forceY(d => d.sector ? sectorCenters[d.sector].y : height/2).strength(0.15))
        .force("collide", d3.forceCollide(d => d.r + 2).iterations(4))
        .on("tick", ticked);

    // Render Bubbles
    const bubbleGroup = container.append("g").attr("class", "bubbles");

    const bubbles = bubbleGroup.selectAll(".bubble")
        .data(nodes)
        .enter()
        .append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.r)
        .attr("fill", d => d.sector ? colorScale(d.sector) : "#999")
        .attr("id", d => "bubble-" + d.ticker)
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip)
        .on("click", handleBubbleClick);

    // Labels
    const labels = container.append("g")
        .selectAll(".bubble-text")
        .data(nodes)
        .enter()
        .append("text")
        .attr("class", "bubble-text")
        .text(d => d.ticker)
        .style("font-size", d => Math.min(2 * d.r, (2 * d.r - 8) / d.ticker.length * 1.5) + "px") // simple dynamic font sizing
        .attr("dy", ".35em")
        .style("pointer-events", "none");

    // Legends
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", "translate(20, 20)");

    sectors.forEach((sector, i) => {
        const g = legend.append("g")
            .attr("class", "legend-item")
            .attr("transform", `translate(0, ${i * 20})`);

        g.append("rect")
            .attr("width", 15)
            .attr("height", 15)
            .attr("fill", colorScale(sector));

        g.append("text")
            .attr("x", 20)
            .attr("y", 12)
            .text(sector)
            .style("font-size", "12px");
    });

    function ticked() {
        bubbles
            .attr("cx", d => d.x)
            .attr("cy", d => d.y);

        labels
            .attr("x", d => d.x)
            .attr("y", d => d.y);
    }

    // --- Table ---
    const tableBody = d3.select("#data-table tbody");

    const rows = tableBody.selectAll("tr")
        .data(nodes)
        .enter()
        .append("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", handleRowClick);

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d["full name"]);
    rows.append("td").text(d => d.sector || "N/A"); // ETFs might have missing sector? Data check needed.
    rows.append("td").text(d => formatMarketCap(d.marketCapVal));

    // --- Interactions ---

    let currentSelection = null;

    function handleBubbleClick(event, d) {
        selectItem(d);
        event.stopPropagation();
    }

    function handleRowClick(event, d) {
        selectItem(d);
        event.stopPropagation();
    }

    function selectItem(d) {
        // Clear previous
        if (currentSelection) {
            d3.select("#bubble-" + currentSelection.ticker).classed("highlighted", false);
            d3.select("#row-" + currentSelection.ticker).classed("highlighted", false);
        }

        // Set new
        currentSelection = d;
        d3.select("#bubble-" + d.ticker).classed("highlighted", true);

        const row = d3.select("#row-" + d.ticker);
        row.classed("highlighted", true);

        // Scroll row into view
        const rowNode = row.node();
        if (rowNode) {
            rowNode.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }

    // Clicking background clears selection
    d3.select("body").on("click", () => {
        if (currentSelection) {
            d3.select("#bubble-" + currentSelection.ticker).classed("highlighted", false);
            d3.select("#row-" + currentSelection.ticker).classed("highlighted", false);
            currentSelection = null;
        }
    });

    // Tooltip
    const tooltip = d3.select("#tooltip");

    function showTooltip(event, d) {
        // Check conditions for tooltip: "ETF entries have no marketCap, country, or website data, so do not show tooltip for them"
        if (!d.marketCap || d.marketCap === "" || !d.country) {
            return; 
        }

        tooltip.transition().duration(200).style("opacity", .9);
        tooltip.html(`
            <h4>${d.ticker}</h4>
            <p><strong>Name:</strong> ${d["full name"]}</p>
            <p><strong>Sector:</strong> ${d.sector}</p>
            <p><strong>Market Cap:</strong> ${formatMarketCap(d.marketCapVal)}</p>
        `)
        .style("left", (event.pageX + 10) + "px")
        .style("top", (event.pageY - 28) + "px");
    }

    function hideTooltip(event, d) {
        tooltip.transition().duration(500).style("opacity", 0);
    }

});
